# -*- coding: utf-8 -*-
from itbase import *

IT07 = F('XX', 'Qué es el tawatur', 'Tawatur',
 'Ibn Taymiyya define el tawatur por el conocimiento que produce en quien oye, no por un número fijo de transmisores; y sostiene que un informe aceptado por la comunidad también puede dar certeza.',
 'Es la regla con la que luego juzga la transmisión de los Evangelios y de la crucifixión (véase IT08).',
 ['maj'], FOOT,
 [
  Q('T5-W-MF18-49', es='«En cuanto al número con el que se alcanza el tawatur, algunos le fijaron una cifra limitada, y entre ellos se discrepa: más de cuatro, doce, cuarenta, setenta, trescientos trece, y otras. [[k:Todas estas opiniones son falsas]], por equivalerse en la pretensión. Lo correcto, que sostiene la mayoría, es que [[k:el tawatur no tiene un número limitado]]: el conocimiento que produce un informe se produce en el corazón por necesidad, como la saciedad tras comer y la sed saciada al beber; y no hay una cantidad fija con la que cada uno se sacie.»',
     theme=['W'], clar='Es su definición central: tawatur no es un número, sino el conocimiento necesario que se produce en el oyente. Lectura (mía): como el criterio es el conocimiento producido, depende de quién escucha.'),
  Q('T5-W-MF18-50b', es='«Si el informe fue tawatur para unos y no para otros, y el conocimiento de su veracidad se produce en unos y no en otros, [[k:quien ha obtenido el conocimiento de él debe creerlo y obrar conforme a él]], como es obligatorio en los casos análogos.»',
     theme=['W'], clar='Admite expresamente que un informe puede ser tawatur «para unos y no para otros»: el criterio es relativo al oyente. Se refiere a informes de hadices de normas rituales y jurídicas, no a los cristianos; ese uso viene después (IT08).'),
  Q('T5-W-MF18-40a', es='«El informe aislado (khabar al-wahid) aceptado con asentimiento [[k:produce conocimiento]] para la mayoría de los sabios, de entre los seguidores de Abu Hanifa, Malik, al-Shafi\'i y Ahmad, y es lo que dicen la mayoría de los seguidores de al-Ash\'ari, como al-Isfara\'ini e Ibn Furak. Pues, aunque en sí mismo solo da opinión, cuando se le añade el consenso de los expertos en hadiz en aceptarlo como veraz, [[k:equivale al consenso de los juristas sobre una norma]], apoyada en una apariencia, una analogía o un informe aislado: esa norma se vuelve concluyente para la mayoría, aunque sin el consenso no lo sea.»',
     theme=['W'], clar='Es la regla de la «aceptación por la comunidad» (talaqqi bi-l-qabul): un informe aislado aceptado por los expertos del hadiz da certeza. Con ella sostiene que la mayor parte de al-Bujari y Muslim es cierta (vol. 18, p. 41).'),
 ])

_L1 = dict(head='Lo que dicen los propios Evangelios', txt='Lucas abre su Evangelio diciendo que lo escribe tras [[k:recibir lo transmitido por testigos oculares]] desde el principio y por «haberlo investigado todo con diligencia»; y Jn 21:24 presenta como autor al discípulo que «da testimonio de estas cosas».', orig='«Even as they delivered them unto us, which from the beginning were eyewitnesses, and ministers of the word» (Lc 1:2) · «This is the disciple which testifieth of these things, and wrote these things» (Jn 21:24)', src='Biblia del Rey Jacobo (KJV, dominio público).')
_L2 = dict(head='Lo que dicen los propios Evangelios', txt='Marcos: «todos lo dejaron y huyeron» (14:50); pero [[k:las mujeres miraban desde lejos]] (15:40) y, según Lucas, también «todos sus conocidos» (23:49). Y en Juan, [[k:junto a la cruz estaba el discípulo a quien amaba]] (19:25-27), y se añade: «el que lo vio ha dado testimonio, y su testimonio es verdadero» (19:35).', orig='«they all forsook him, and fled» (Mc 14:50) · «there were also women looking on afar off» (Mc 15:40) · «his mother, and the disciple standing by, whom he loved» (Jn 19:26) · «he that saw it bare record, and his record is true» (Jn 19:35)', src='Biblia del Rey Jacobo (KJV, dominio público).')
IT08 = F('XX', 'Tawatur: Evangelios, crucifixión y Corán', 'Tawatur',
 'Ibn Taymiyya aplica su criterio de transmisión a los Evangelios, a la crucifixión y a las lecturas del Corán.',
 'Aquí se ve cómo usa el tawatur contra los cristianos y qué exige al Corán; se contrasta con lo que dicen los propios Evangelios.',
 ['jawab', 'maj'], FOOT,
 [
  Q('T5-WC-JS2-272', es='«Esto apoya que hicieron lo mismo con la Torá y el Evangelio. Pues si el Corán, cuya exégesis y cuyo sentido general y particular se conocen y se transmitieron del Mensajero por tawatur hasta conocerse su significado con ciencia cierta y necesaria, [[k:aun así [ellos] tergiversan su sentido y desvían las palabras de su lugar]], ¿qué no harán con la Torá y el Evangelio, [[k:cuya letra y cuyo sentido no se transmitieron como se transmitió el Corán]]? Y entre los seguidores de esos libros no hay quien defienda su letra y su sentido como los musulmanes defienden la letra y el sentido del Corán.»',
     theme=['W', 'C'], verdict='parcial', clar='«Ellos», en este pasaje, son los cristianos que (según el párrafo anterior) interpretan versículos del Corán a su favor, como «ese Libro» = el Evangelio. Es su argumento: si ellos manipulan hasta un texto tan transmitido, qué no harán con los suyos.',
     vtxt='Acierta en lo que afirma: los Evangelios no se transmitieron memorizados por una multitud, como el Corán. Pero no responde a lo que los propios textos dicen de su origen (transmisión de testigos oculares, Lc 1:1-4) y su afirmación de que nadie defiende su texto es una generalización suya, sin cifras.', christian=_L1),
  Q('T6-07', es='«Y ninguno de los cristianos presenció esto con ellos: [[k:los apóstoles estaban asustados y ausentes, y ninguno de ellos presenció la crucifixión]]. Quienes la presenciaron fueron los judíos, y ellos fueron quienes informaron a la gente de que habían crucificado al Mesías; y quienes transmitieron que el Mesías fue crucificado, de entre los cristianos y otros, solo lo transmitieron de aquellos judíos, que eran [[k:una guardia de auxiliares de los opresores, no una multitud]] cuyo acuerdo para mentir fuera imposible.»',
     theme=['W', 'C'], verdict='parcial', clar='Es su prueba de que la crucifixión no es mutawatir: pocos testigos, todos hostiles, y los discípulos ausentes. Lo usa para explicar Corán 4:157. «Shurat» («guardia») es una lectura mía de «شرط».',
     vtxt='Hay base para decir que, según los sinópticos, los discípulos huyeron y las mujeres miraban de lejos. Pero afirmar que ningún cristiano presenció la crucifixión contradice a Juan 19:25-27 y 19:35, y los Evangelios no atribuyen su relato a informantes judíos sino a esos testigos.', christian=_L2),
  SP('maj', 'وتجوز القراءة في الصلاة وخارجها', 'وليست شاذة حينئذ',
     es='«Y se puede recitar en la oración y fuera de ella con las lecturas [[k:establecidas]] que concuerdan con el trazo del códice (rasm), tal como se establecieron esas lecturas; y entonces no son anómalas (shadhdha).»',
     theme=['W'], clar='Es el final de una fatua sobre las lecturas del Corán. Su criterio para permitir una lectura es que esté «establecida» (thabita) y concuerde con el rasm; no exige tawatur de cada lectura. En la misma fatua informa (en la Risala fi \'ilm al-qira\'at, vol. 13) de que la mayoría rechaza las lecturas anómalas en la oración porque «no se transmitieron como tawatur del Profeta», y dice que los «siete ahruf» del hadiz no son las siete lecturas de Ibn Mujahid. Lectura (mía): para el Corán el criterio es «establecida»; para los Evangelios exige tawatur de la letra.'),
 ])

IT09 = F('XX', 'La carta de Pablo y el método de al-Jawab al-Sahih', 'Cristianos',
 '«Al-Jawab al-Sahih» responde a una carta atribuida a Pablo de Antioquía, obispo melquita de Sidón; Ibn Taymiyya dice que la citará con sus palabras y la irá respondiendo.',
 'Es la base de todo lo que sigue: de qué cristianismo parte. ¿Cita bien su fuente?',
 ['jawab'], FOOT,
 [
  SP('jawab', 'وما ذكروه في هذا الكتاب هو عمدتهم', 'كتبها إلى بعض أصدقائه',
     es='«Lo que mencionaron en este libro es [[k:su sostén principal, el que usan sus sabios]] en esta época y antes de ella, aunque unos añaden a otros según las circunstancias; pues a esta epístola los encontramos apoyándose en ella ya antes, sus sabios se la transmiten entre ellos, hay copias antiguas, y se atribuye a Pablo el monje, obispo de Sidón de Antioquía, que la escribió a uno de sus amigos.»',
     theme=['C'], verdict='fiel', clar='Identifica la carta, su autor y su difusión. Dice «a uno de sus amigos»: no dice que fuera musulmán (las fuentes modernas hablan de una «carta a un amigo musulmán»).',
     vtxt='Datos exactos: es una carta de Pablo de Antioquía (melquita, obispo de Sidón) que circuló desde Chipre (según Bogataj 2019, leído por un investigador). Matiz honesto: presenta la carta de un obispo melquita como «el sostén de sus sabios»: es una muestra, no la doctrina de todas las Iglesias.'),
  Q('T7-06', es='«Y yo mencionaré lo que dijeron [[k:con sus palabras exactas]], sección por sección, y seguiré cada sección con la respuesta que le corresponde, en lo accesorio y en lo fundamental, en lo que ata y en lo que desata.»',
     theme=['C'], verdict='nov', clar='Es su declaración de método. Solo la sección 1 de la carta aparece marcada como cita literal (con «dijeron»); en las demás secciones la comprobación contra la edición de referencia (Khoury, 1964) no pude hacerla.',
     vtxt='No verificable en conjunto: la cita literal solo se ha podido contrastar en la primera sección.'),
  Q('T7-09', es='«Dijeron: «Cuando vimos esto supimos que [Muhammad] no vino a nosotros, sino [[k:a la ignorancia de los árabes]], a quienes —dijo— no había llegado antes de él ningún mensajero ni advertidor, y que no estamos obligados a seguirlo, pues a nosotros ya nos llegaron mensajeros antes de él, que nos hablaron en nuestras lenguas, nos advirtieron con nuestra religión, a la que nos aferramos hoy, y nos entregaron la Torá y el Evangelio en nuestras lenguas, como atestigua este libro que trajo este hombre cuando dice en la sura de Abraham: «No enviamos a ningún mensajero sino con la lengua de su pueblo, para que les explique» [14:4].»»',
     theme=['C'], verdict='fiel', clar='Es el argumento con el que abre la carta (sección 1): Muhammad fue enviado solo a los árabes. El texto no va entre comillas en la obra, pero se presenta como «sus palabras».',
     vtxt='Según el investigador que lo cotejó, coincide en lo esencial con la traducción inglesa de la carta (Bogataj 2019, § 7); no pude comprobar el árabe de la edición de Khoury.'),
 ])

_CH_NIC = dict(head='Lo que dicen los credos', txt='Credo niceno-constantinopolitano: el Hijo es [[k:de una sola sustancia con el Padre]]. Credo de Atanasio, v. 15-16: «Así el Padre es Dios, el Hijo es Dios y el Espíritu Santo es Dios. Y, sin embargo, [[k:no son tres Dioses, sino un solo Dios]]».', orig='«begotten, not made, being of one substance [essence] with the Father» · «So the Father is God: the Son is God: and the Holy Ghost is God. And yet they are not three Gods: but one God.»', src='Philip Schaff, Creeds of Christendom II (CCEL; traducciones inglesas de dominio público).')
_CH_PER = dict(head='Lo que dicen los Padres y los teólogos: personas, no atributos', txt='Gregorio Nacianceno: si el Espíritu «es una sustancia y no [[k:un atributo de la sustancia]]», se concebirá como criatura o como Dios. Santo Tomás: la «persona» en Dios [[k:significa una relación subsistente en la naturaleza divina]]. Juan Damasceno: una sola esencia, divinidad y poder, [[k:dada a conocer en tres subsistencias perfectas]].', orig='«But if He is a Substance and not an attribute of Substance, He will be conceived of either as a Creature of God, or as God.» · «signifies relation as subsisting in the divine nature» · «made known in three perfect subsistences»', src='Gregorio Nacianceno, Or. 31, § 6 (NPNF2 7); Tomás de Aquino, S. Th. I q.39 a.1; Juan Damasceno, Exposición de la fe ortodoxa I.8 (NPNF2 9). Traducciones inglesas de dominio público.')
_CH_ARAB = dict(head='Autores cristianos árabes (fuente secundaria)', txt='Según Husseini (2011, pp. 376 y 386), Abu Ra\'ita y \'Ammar al-Basri [[k:no equiparan las hipóstasis con atributos]]. Lo que sí hay es una fórmula como la de Pablo (esencia, habla, vida), que Ibn Taymiyya cita; y, según él, Yahya ibn \'Adi usaba la analogía de Zayd (médico, calculista y escriba) para explicar el \'uqnum (no comprobada en el texto de Yahya).', src='Husseini, tesis doctoral, Birmingham, 2011, leída en parte por un investigador; no la he comprobado yo.')
_CH_HEB = dict(head='Lo que dice el Nuevo Testamento', txt='Hebreos 1:3 en griego dice que el Hijo es [[k:«imagen exacta de su hipóstasis»]] (χαρακτὴρ τῆς ὑποστάσεως αὐτοῦ); la versión del Rey Jacobo traduce «imagen de su persona». La palabra «hipóstasis» sí figura, pues, en un texto del Nuevo Testamento, aunque Ibn Taymiyya pensara en la versión árabe o siríaca que tenía a mano.', orig='«Who being the brightness of his glory, and the express image of his person» (Heb 1:3, KJV)', src='Biblia del Rey Jacobo (KJV, dominio público); griego comprobado por un investigador en biblehub.')
IT10 = F('XX', 'La Trinidad como «atributos»', 'Cristianos',
 'Ibn Taymiyya explica la Trinidad como la identificación de Padre, Hijo y Espíritu Santo con atributos de Dios (existencia, palabra, vida) y critica esa lectura.',
 'Aquí se juega el «hombre de paja»: ¿es eso lo que dicen los cristianos? Respuesta honesta: es lo que dice una carta cristiana árabe, no lo que dicen los credos.',
 ['jawab'], FOOT,
 [
  Q('T8-C01', es='«[…] la esencia, para nosotros, es el Padre, que es el principio de los otros dos; el habla, el Hijo, que nace de él como nace el habla de la mente; y la vida, el Espíritu Santo. [[k:y estos son nombres con los que no lo nombramos nosotros]].»',
     theme=['C'], verdict='fiel', clar='Aquí Ibn Taymiyya no habla en su voz: reproduce un pasaje de la carta cristiana que atribuye a Pablo de Antioquía (vol. 3, pp. 182–183; se introduce con «dijo el que lo cuenta de ellos»). Dice que esos nombres vienen de la Escritura.',
     vtxt='Fiel como cita: es un testimonio real de cómo algunos apologistas cristianos árabes explicaban la Trinidad (esencia, habla, vida). Pero eso no es lo que dicen los credos: no equiparan a las personas con atributos.', christian=_CH_PER),
  Q('T8-C02', es='«Muchos de ellos dicen: el Padre es la existencia, el Hijo es la Palabra y el Espíritu Santo es la vida. Y entre ellos hay quien dice: no, el Padre es la existencia, el Hijo es la Palabra y el Espíritu Santo es el poder.»',
     theme=['C'], verdict='parcial', clar='Aquí habla en su propia voz y generaliza («muchos de ellos») sin nombrar autores ni libros; dice que lo ha visto «en libros de ellos». La primera tríada coincide con la fórmula de Pablo; la variante «poder» no está comprobada.',
     vtxt='Parcialmente fiel: la primera fórmula es real, pero él no nombra fuentes ni demuestra que sea la de «muchos»; y presentarla como la doctrina cristiana en general no encaja con los credos ni con los Padres.', christian=_CH_ARAB),
  Q('T11-C07', es='«[…] que su doctrina de las hipóstasis, aparte de ser falsa para la razón y la ley, [[k:no la proclama ningún libro de los que ellos tienen]]: esta palabra no se encuentra en ninguno de los libros de los profetas que tienen en sus manos ni en las palabras de los apóstoles; es una palabra que inventaron, y se dice que es romana. Se ha dicho que «hipóstasis» en su lengua significa «origen», y por eso [[k:se contradicen al explicar las hipóstasis]]: unas veces dicen «personas», otras «propiedades», otras «atributos», otras «sustancias», y otras hacen de la hipóstasis un nombre de la esencia y el atributo juntos; y esta es la explicación de sus expertos.»',
     theme=['C'], verdict='parcial', clar='Es un argumento suyo (de ahí «falsa para la razón y la ley» es su juicio). Contiene un dato verdadero —las glosas del término varían entre autores cristianos— y una afirmación discutible: que la palabra no está en los libros que tienen.',
     vtxt='Mitad cierto: los cristianos explican el término de maneras distintas. Mitad impreciso: «hipóstasis» sí figura en Hebreos 1:3 (griego), aunque no lo vea en las versiones árabes o siríacas que cita.', christian=_CH_HEB),
 ])

_CH_ATH_20 = dict(head='Lo que dicen los credos y Agustín', txt='Credo de Atanasio, v. 20: «Así, [[k:la religión católica nos prohíbe decir que hay tres Dioses]] o tres Señores». Agustín, De Trinitate V, 8: «no decimos que la Trinidad suprema sea tres Dioses, sino [[k:un solo Dios]]».', orig='«So are we forbidden by the Catholic Religion: to say, There be [are] three Gods, or three Lords.» · «we do not say that the very Supreme Trinity itself is three Gods, but one God»', src='Schaff, Creeds of Christendom II; Agustín, De Trinitate V.8 (NPNF1 3). Traducciones inglesas de dominio público.')
_CH_EQ = dict(head='Lo que dicen los credos y el IV Concilio de Letrán', txt='Credo de Atanasio, v. 25-26: en esta Trinidad nadie es antes ni después de otro, [[k:nadie es mayor ni menor]]; las tres personas son coeternas y coiguales. Letrán IV (1215): hay un solo Dios verdadero, [[k:tres Personas pero una sola esencia, sustancia o naturaleza absolutamente simple]].', orig='«none is afore, or after another: none is greater, or less than another … the whole three Persons are coeternal, and coequal» · «three Persons indeed but one essense [sic], substance, or nature absolutely simple»', src='Schaff, Creeds of Christendom II; Fordham Medieval Sourcebook (Letrán IV, canon 1; «essense» es la grafía de esa página).')
IT11 = F('XX', '«Tres sustancias, tres dioses»', 'Cristianos',
 'Ibn Taymiyya argumenta que la fórmula del credo («de una sustancia con el Padre») implica tres sustancias y, por tanto, tres dioses; y que decir a la vez «un solo Dios» es contradecirse.',
 'Es su argumento racional central contra la Trinidad. ¿Describe bien lo que los cristianos dicen o lo que él cree que se sigue de lo que dicen?',
 ['jawab', 'maj'], FOOT,
 [
  Q('T8-C10', es='«[…] y a la sustancia del Padre solo la iguala otra sustancia, de modo que el Hijo ha de ser una segunda sustancia y el Espíritu Santo una tercera, como se verá. Y esto es [[k:una declaración de tres sustancias y de tres dioses]]; y, con todo, dicen: solo afirmamos una sustancia y un solo Dios, y esto es [[k:juntar dos contradictorios]].»',
     theme=['C'], verdict='parcial', clar='Es su argumento, no una cita cristiana: la frase del credo (el Hijo «igual al Padre en sustancia») la cita con exactitud, pero la conclusión («tres sustancias, tres dioses») es una inferencia suya, que presupone que «sustancia» en Dios es algo numerable.',
     vtxt='La cita es exacta; la conclusión es su inferencia. Los credos dicen una sola sustancia y tres personas, y prohíben decir tres dioses. Un argumento por reducción al absurdo es legítimo, pero en este pasaje no discute la distinción cristiana entre «sustancia» (común) y «persona» (hipóstasis).', christian=_CH_NIC),
  Q('T8-C13', corr=[('يناقضون','يتناقضون')], es='«Tampoco ellos dicen tres señores ni tres dioses: si esto [la triple repetición] indicara tres señores y tres dioses, indicaría lo contrario de lo que dicen; [[k:ellos pretenden afirmar un solo Dios]], pero se contradicen y proclaman tres dioses, y dicen: [son] un solo Dios.»',
     theme=['C'], verdict='fiel', clar='Responde al «Santo, Santo, Santo» (Is 6:3), que la carta cristiana alegaba a favor de la Trinidad. Admite que los cristianos NO dicen tres dioses; su acusación es que lo dicen en la práctica.',
     vtxt='Fiel en lo que reconoce: los cristianos niegan decir tres dioses. Su acusación de contradicción es un argumento, no un informe sobre lo que creen.', christian=_CH_ATH_20),
  Q('T1-MF-V11-050C', es='«No hay entre todos los incrédulos quien haya puesto a Dios un asociado igual a Él en esencia, atributos y actos: esto no lo dijo nunca nadie, [[k:ni los zoroastrianos dualistas, ni la gente de la Trinidad]], ni los sabeos que adoran astros y ángeles, ni quienes adoran a profetas y justos, ni los adoradores de estatuas y tumbas.»',
     theme=['T', 'C'], verdict='parcial', clar='Es su afirmación en una fatua sobre el tawhid: incluye a los trinitarios entre los asociacionistas («shirk»), pero dice que ninguno puso un asociado «igual» a Dios. Los credos dicen que las tres personas son iguales y coeternas, pero no las presentan como asociados de Dios sino como Dios mismo.',
     vtxt='Desajuste de categoría: «asociado» no es lo que dice el credo. Lo que sí dice es igualdad de las tres personas (coiguales), y eso él lo niega en este pasaje.', christian=_CH_EQ),
 ])

_CH_CHAL = dict(head='Lo que dice el Concilio de Calcedonia (451)', txt='«Un solo y mismo Cristo, Hijo, Señor, Unigénito, que ha de ser reconocido [[k:en dos naturalezas, sin confusión, sin cambio, sin división, sin separación]]; […] nacido de la Virgen María, la Madre de Dios, según la humanidad».', orig='«one and the same Christ, Son, Lord, Only-begotten, to be acknowledged in two natures, inconfusedly, unchangeably, indivisibly, inseparably … born of the Virgin Mary, the Mother of God, according to the Manhood»', src='Definición de Calcedonia, en Schaff, Creeds of Christendom II (CCEL; traducción inglesa de dominio público).')
_CH_PASS = dict(head='Lo que dicen Cirilo, León y Santo Tomás', txt='Cirilo de Alejandría (anatema 12): [[k:el Verbo de Dios sufrió en la carne]], fue crucificado en la carne. León Magno: «el Dios impasible no desdeñó ser Hombre pasible». Santo Tomás: «el Señor de la gloria es llamado crucificado, no como Señor de la gloria, [[k:sino como hombre capaz de sufrir]]».', orig='«Whosoever shall not recognize that the Word of God suffered in the flesh, that he was crucified in the flesh…» · «the impassible God did not disdain to be passible Man» · «The Lord of glory is said to be crucified, not as the Lord of glory, but as a man capable of suffering.»', src='Cirilo, Doce anatemas (NPNF2 14); León Magno, Tomus ad Flavianum (NPNF2 14); Tomás de Aquino, S. Th. III q.46 a.12 ad 1. Traducciones inglesas de dominio público.')
_CH_MARIA = dict(head='Lo que dicen el Concilio de Nicea II (787) y la oración tradicional', txt='Nicea II distingue [[k:«saludo y reverencia honorífica»]] (proskynesis) de [[k:la verdadera adoración de fe (latreia), «que pertenece solo a la naturaleza divina»]]. Y la oración tradicional dice a María: «Santa María, Madre de Dios, [[k:ruega por nosotros, pecadores]]» (no «perdónanos»).', orig='«due salutation and honourable reverence … not indeed that true worship of faith (latreian) which pertains alone to the divine nature»', src='Concilio de Nicea II, Definición (NPNF2 14; Fordham Medieval Sourcebook); Ave María (texto litúrgico tradicional).')
IT12 = F('XX', 'Encarnación, cruz y María', 'Cristianos',
 'Ibn Taymiyya describe la cristología de las Iglesias (melquitas, jacobitas) y la devoción a María, y critica la encarnación, la muerte de «Dios» y el culto a María.',
 'Aquí acierta en una parte (la fórmula melquita) y se equivoca o generaliza en otra (jacobitas, María).',
 ['jawab'], FOOT,
 [
  Q('T10-04', es='«Luego examiné lo que dicen los melquitas, que son los bizantinos y la mayoría de los cristianos, y vi que dicen: el Hijo eterno, que es Dios el Verbo, [[k:se encarnó de María con una encarnación completa]], como los cuerpos de los demás hombres, y se le unió en ese cuerpo un alma completa, con razón, conocimiento y ciencia, como las almas de los demás hombres; de modo que fue hombre por el alma y el cuerpo, que son de la sustancia de los hombres, y Dios por la sustancia de la divinidad, [[k:una sola persona y dos naturalezas]], y cada una de las dos naturalezas tiene una voluntad completa.»',
     theme=['C'], verdict='fiel', clar='No es su voz: Ibn Taymiyya cita la carta de al-Hasan ibn Ayyub, un antiguo cristiano convertido al islam (vol. 4, p. 92), que resume la doctrina melquita (de Calcedonia).',
     vtxt='Fiel en lo esencial: una sola persona, dos naturalezas, sin confusión (Calcedonia). «Cada naturaleza con su voluntad» es la doctrina bizantina posterior (III Concilio de Constantinopla, 681), no Calcedonia mismo. Es el resumen de un converso, no un documento melquita.', christian=_CH_CHAL),
  Q('T10-03', es='«Y dijeron: «María dio a luz a Dios» —¡elevado sea Dios por encima de lo que dicen!—, y que [[k:Dios murió, padeció y fue crucificado encarnado]], fue enterrado, resucitó de entre los muertos y subió al cielo; y llegaron a decir algo que, si se presentara al cielo, se rasgaría; a la tierra, se abriría; y a los montes, se derrumbarían.»',
     theme=['C'], verdict='parcial', clar='Es de nuevo la carta de al-Hasan ibn Ayyub (convertido), que resume la doctrina de los jacobitas (miafisitas); él cita sus palabras como suyas. Los melquitas y nestorianos la rechazan, como dice el propio Ibn Taymiyya en otro lugar (vol. 3, pp. 493–494).',
     vtxt='Hay un fondo real: «María, Madre de Dios» y «el Verbo sufrió en la carne» son fórmulas cristianas (Éfeso, Cirilo). Pero «Dios murió» sin matiz es una caricatura: los credos dicen que murió en la naturaleza humana, no en la divina. Es parcialmente fiel.', christian=_CH_PASS),
  Q('T10-16', es='«Pues ellos adoran a María y la invocan con lo que invocan a Dios —glorificado sea— y al Mesías, y la hacen dios como hacen dios al Mesías: dicen «¡Oh Madre de Dios, perdónanos y ten misericordia de nosotros!» y cosas así, y le piden [[k:lo que piden a Dios]].»',
     theme=['C'], verdict='paja', clar='Habla en su voz y generaliza («ellos»). En otro pasaje (vol. 4, pp. 255–256) distingue a quienes le piden «intercede por nosotros» de quienes, según dice, la adoran como al Mesías (atribuyéndolo a otros); aquí lo afirma sin esa distinción.',
     vtxt='Hombre de paja si se dice de «los cristianos» en general: la oración mariana tradicional pide a María que ruegue por nosotros, no que perdone, y Nicea II (787) reserva la adoración (latreia) a Dios.', christian=_CH_MARIA),
 ])
